//! Independent from-scratch reimplementation of mapbox/earcut.hpp v2.2.4
//! (the C++ port of earcut.js 2.2.x), written from knowledge of the canonical
//! algorithm.  Arena-of-nodes instead of raw pointers; `usize` node ids stand
//! in for `Node*`, `NULL` is `usize::MAX` / `None`.

pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy)]
pub struct Node {
    pub i: u32,
    pub x: f64,
    pub y: f64,
    pub prev: usize,
    pub next: usize,
    pub z: i32,
    pub prev_z: usize,
    pub next_z: usize,
    pub steiner: bool,
}

pub struct Earcut {
    pub nodes: Vec<Node>,
    pub indices: Vec<u32>,
    vertices: usize,
    hashing: bool,
    min_x: f64,
    min_y: f64,
    max_x: f64,
    max_y: f64,
    inv_size: f64,
}

macro_rules! n {
    ($s:expr, $i:expr) => {
        $s.nodes[$i]
    };
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) -> Vec<u32> {
        self.indices.clear();
        self.nodes.clear();
        self.vertices = 0;

        if points.is_empty() {
            return Vec::new();
        }

        // threshold loop, verbatim from earcut.hpp
        let mut threshold: i32 = 80;
        let mut i = 0usize;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            i += 1;
        }

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || n!(self, outer_node).prev == n!(self, outer_node).next {
            return Vec::new();
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        self.hashing = threshold < 0;
        if self.hashing {
            // NOTE: earcut.hpp walks the *linked list* (post hole-merge), not
            // the raw outer-ring coordinate array like earcut.js does.
            let mut p = n!(self, outer_node).next;
            self.min_x = n!(self, outer_node).x;
            self.max_x = self.min_x;
            self.min_y = n!(self, outer_node).y;
            self.max_y = self.min_y;
            loop {
                let x = n!(self, p).x;
                let y = n!(self, p).y;
                if x < self.min_x {
                    self.min_x = x;
                }
                if y < self.min_y {
                    self.min_y = y;
                }
                if x > self.max_x {
                    self.max_x = x;
                }
                if y > self.max_y {
                    self.max_y = y;
                }
                p = n!(self, p).next;
                if p == outer_node {
                    break;
                }
            }
            self.inv_size = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.indices.clone()
    }

    fn create(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        self.nodes.len() - 1
    }

    fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.create(i as u32, pt[0], pt[1]);
        if last == NIL {
            n!(self, p).prev = p;
            n!(self, p).next = p;
        } else {
            let ln = n!(self, last).next;
            n!(self, p).next = ln;
            n!(self, p).prev = last;
            n!(self, ln).prev = p;
            n!(self, last).next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let nx = n!(self, p).next;
        let pv = n!(self, p).prev;
        n!(self, nx).prev = pv;
        n!(self, pv).next = nx;

        let pz = n!(self, p).prev_z;
        let nz = n!(self, p).next_z;
        if pz != NIL {
            n!(self, pz).next_z = nz;
        }
        if nz != NIL {
            n!(self, nz).prev_z = pz;
        }
    }

    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut sum = 0.0f64;
        let mut j = if len > 0 { len - 1 } else { 0 };
        let mut i = 0usize;
        while i < len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
            i += 1;
        }

        let mut last = NIL;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NIL {
            let nx = n!(self, last).next;
            if self.equals(last, nx) {
                self.remove_node(last);
                last = nx;
            }
        }

        self.vertices += len;
        last
    }

    fn filter_points(&mut self, start: usize, end_in: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end_in == NIL { start } else { end_in };

        let mut p = start;
        let mut again;
        loop {
            again = false;
            let nx = n!(self, p).next;
            let pv = n!(self, p).prev;
            if !n!(self, p).steiner && (self.equals(p, nx) || self.area(pv, p, nx) == 0.0) {
                self.remove_node(p);
                p = n!(self, p).prev;
                end = p;
                if p == n!(self, p).next {
                    break;
                }
                again = true;
            } else {
                p = nx;
            }
            if !(again || p != end) {
                break;
            }
        }
        end
    }

    fn earcut_linked(&mut self, ear_in: usize, pass: i32) {
        let mut ear = ear_in;
        if ear == NIL {
            return;
        }

        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        while n!(self, ear).prev != n!(self, ear).next {
            let prev = n!(self, ear).prev;
            let next = n!(self, ear).next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                self.indices.push(n!(self, prev).i);
                self.indices.push(n!(self, ear).i);
                self.indices.push(n!(self, next).i);

                self.remove_node(ear);

                ear = n!(self, next).next;
                stop = ear;
                continue;
            }

            ear = next;

            if ear == stop {
                if pass == 0 {
                    let f = self.filter_points(ear, NIL);
                    self.earcut_linked(f, 1);
                } else if pass == 1 {
                    let f = self.filter_points(ear, NIL);
                    let e2 = self.cure_local_intersections(f);
                    self.earcut_linked(e2, 2);
                } else if pass == 2 {
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let mut p = self.nodes[self.nodes[ear].next].next;
        while p != self.nodes[ear].prev {
            if point_in_triangle(
                ax,
                ay,
                bx,
                by,
                cx,
                cy,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }
        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let min_tx = f64::min(ax, f64::min(bx, cx));
        let min_ty = f64::min(ay, f64::min(by, cy));
        let max_tx = f64::max(ax, f64::max(bx, cx));
        let max_ty = f64::max(ay, f64::max(by, cy));

        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let mut p = self.nodes[ear].prev_z;
        let mut q = self.nodes[ear].next_z;

        while p != NIL && self.nodes[p].z >= min_z && q != NIL && self.nodes[q].z <= max_z {
            let np = &self.nodes[p];
            if np.x >= min_tx
                && np.x <= max_tx
                && np.y >= min_ty
                && np.y <= max_ty
                && p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, np.x, np.y)
                && self.area(np.prev, p, np.next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;

            let nq = &self.nodes[q];
            if nq.x >= min_tx
                && nq.x <= max_tx
                && nq.y >= min_ty
                && nq.y <= max_ty
                && q != a
                && q != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, nq.x, nq.y)
                && self.area(nq.prev, q, nq.next) >= 0.0
            {
                return false;
            }
            q = self.nodes[q].next_z;
        }

        while p != NIL && self.nodes[p].z >= min_z {
            let np = &self.nodes[p];
            if np.x >= min_tx
                && np.x <= max_tx
                && np.y >= min_ty
                && np.y <= max_ty
                && p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, np.x, np.y)
                && self.area(np.prev, p, np.next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        while q != NIL && self.nodes[q].z <= max_z {
            let nq = &self.nodes[q];
            if nq.x >= min_tx
                && nq.x <= max_tx
                && nq.y >= min_ty
                && nq.y <= max_ty
                && q != self.nodes[ear].prev
                && q != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, nq.x, nq.y)
                && self.area(nq.prev, q, nq.next) >= 0.0
            {
                return false;
            }
            q = self.nodes[q].next_z;
        }

        true
    }

    fn cure_local_intersections(&mut self, start_in: usize) -> usize {
        let mut start = start_in;
        let mut p = start;
        loop {
            let a = n!(self, p).prev;
            let pn = n!(self, p).next;
            let b = n!(self, pn).next;

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(n!(self, a).i);
                self.indices.push(n!(self, p).i);
                self.indices.push(n!(self, b).i);

                self.remove_node(p);
                let pn2 = n!(self, p).next;
                self.remove_node(pn2);

                p = b;
                start = b;
            }
            p = n!(self, p).next;
            if p == start {
                break;
            }
        }
        self.filter_points(p, NIL)
    }

    fn split_earcut(&mut self, start: usize) {
        let mut a = start;
        loop {
            let an = n!(self, a).next;
            let mut b = n!(self, an).next;
            while b != n!(self, a).prev {
                if n!(self, a).i != n!(self, b).i && self.is_valid_diagonal(a, b) {
                    let mut c = self.split_polygon(a, b);

                    let a_next = n!(self, a).next;
                    let mut a2 = self.filter_points(a, a_next);
                    let c_next = n!(self, c).next;
                    c = self.filter_points(c, c_next);
                    // keep names tidy
                    std::mem::swap(&mut a2, &mut a);
                    let _ = a2;

                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = n!(self, b).next;
            }
            a = n!(self, a).next;
            if a == start {
                break;
            }
        }
    }

    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node_in: usize) -> usize {
        let mut outer_node = outer_node_in;
        let mut queue: Vec<usize> = Vec::new();
        for i in 1..points.len() {
            let list = self.linked_list(&points[i], false);
            if list != NIL {
                if list == n!(self, list).next {
                    n!(self, list).steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        // std::sort with `a->x < b->x`; for the small hole counts we test this
        // is insertion-sort in libstdc++, i.e. stable.
        queue.sort_by(|&a, &b| self.nodes[a].x.partial_cmp(&self.nodes[b].x).unwrap());

        for k in 0..queue.len() {
            outer_node = self.eliminate_hole(queue[k], outer_node);
        }
        outer_node
    }

    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        let brn = n!(self, bridge_reverse).next;
        self.filter_points(bridge_reverse, brn);

        let bn = n!(self, bridge).next;
        self.filter_points(bridge, bn)
    }

    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        loop {
            let pn = self.nodes[p].next;
            if hy <= self.nodes[p].y
                && hy >= self.nodes[pn].y
                && self.nodes[pn].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x)
                        / (self.nodes[pn].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.nodes[p].x < self.nodes[pn].x {
                        p
                    } else {
                        pn
                    };
                    if x == hx {
                        return m;
                    }
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = m;
        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = ((hy - py) / (hx - px)).abs();
                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x
                                || (px == self.nodes[m].x
                                    && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan;
                }
            }
            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }
        m
    }

    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if n!(self, p).z == 0 {
                let (x, y) = (n!(self, p).x, n!(self, p).y);
                n!(self, p).z = self.z_order(x, y);
            }
            let pv = n!(self, p).prev;
            let nx = n!(self, p).next;
            n!(self, p).prev_z = pv;
            n!(self, p).next_z = nx;
            p = nx;
            if p == start {
                break;
            }
        }

        let pz = n!(self, p).prev_z;
        n!(self, pz).next_z = NIL;
        n!(self, p).prev_z = NIL;

        self.sort_linked(p);
    }

    fn sort_linked(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut in_size = 1i32;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0i32;
                for _ in 0..in_size {
                    p_size += 1;
                    q = n!(self, q).next_z;
                    if q == NIL {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = n!(self, q).next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = n!(self, p).next_z;
                        p_size -= 1;
                    } else if n!(self, p).z <= n!(self, q).z {
                        e = p;
                        p = n!(self, p).next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = n!(self, q).next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        n!(self, tail).next_z = e;
                    } else {
                        list = e;
                    }
                    n!(self, e).prev_z = tail;
                    tail = e;
                }
                p = q;
            }

            n!(self, tail).next_z = NIL;

            if num_merges <= 1 {
                return list;
            }
            in_size *= 2;
        }
    }

    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bi = self.nodes[b].i;
        (self.nodes[an].i != bi
            && self.nodes[ap].i != bi
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(ap, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0)))
    }

    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
    }

    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true;
        }
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }
        false
    }

    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        qx <= f64::max(px, rx)
            && qx >= f64::min(px, rx)
            && qy <= f64::max(py, ry)
            && qy >= f64::min(py, ry)
    }

    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        false
    }

    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (x0, y0) = (self.nodes[p].x, self.nodes[p].y);
            let (x1, y1) = (self.nodes[pn].x, self.nodes[pn].y);
            if ((y0 > py) != (y1 > py))
                && y1 != y0
                && (px < (x1 - x0) * (py - y0) / (y1 - y0) + x0)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (n!(self, a).i, n!(self, a).x, n!(self, a).y);
        let (bi, bx, by) = (n!(self, b).i, n!(self, b).x, n!(self, b).y);
        let a2 = self.create(ai, ax, ay);
        let b2 = self.create(bi, bx, by);
        let an = n!(self, a).next;
        let bp = n!(self, b).prev;

        n!(self, a).next = b;
        n!(self, b).prev = a;

        n!(self, a2).next = an;
        n!(self, an).prev = a2;

        n!(self, b2).next = a2;
        n!(self, a2).prev = b2;

        n!(self, bp).next = b2;
        n!(self, b2).prev = bp;

        b2
    }

    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }
}

fn sign(v: f64) -> i32 {
    if v > 0.0 {
        1
    } else if v < 0.0 {
        -1
    } else {
        0
    }
}

#[allow(clippy::too_many_arguments)]
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(points)
}

