//! A pure-`std` Rust port of the `mapbox::earcut` polygon triangulation
//! library (`earcut.hpp`).
//!
//! The public surface mirrors the C++ one:
//!
//! ```text
//! std::vector<N> mapbox::earcut<N>(const Polygon& poly)
//! ```
//!
//! becomes
//!
//! ```text
//! fn mapbox::earcut::<N, _, _>(poly: &[Ring]) -> Vec<N>
//! ```
//!
//! where a `Polygon` is a sequence of rings, the first ring being the outer
//! boundary and any remaining rings being holes.

// This library is a general purpose port; the `test10` binary only reaches a
// slice of its surface, so unused-item lints are not informative here.
#![allow(dead_code)]

pub mod earcut;
pub mod geom;
pub mod index;
pub mod node;
pub mod point;

// Convenience re-exports mirroring the `mapbox::` namespace.
#[allow(unused_imports)]
pub use self::earcut::{earcut, Earcut};
#[allow(unused_imports)]
pub use self::index::IndexType;
#[allow(unused_imports)]
pub use self::point::Point2D;
=== point.rs ===
//! Point accessors.
//!
//! Stands in for `mapbox::util::nth<0, Point>::get(p)` / `nth<1, Point>::get(p)`
//! from the C++ library, which is how `earcut.hpp` reads coordinates out of a
//! user supplied point type. Implementing this trait for a custom type is the
//! equivalent of specializing `mapbox::util::nth`.

/// A two dimensional point whose coordinates can be read as `f64`.
pub trait Point2D {
    /// The first coordinate (`nth<0>`).
    fn x(&self) -> f64;
    /// The second coordinate (`nth<1>`).
    fn y(&self) -> f64;
}

impl Point2D for [f64; 2] {
    #[inline]
    fn x(&self) -> f64 {
        self[0]
    }
    #[inline]
    fn y(&self) -> f64 {
        self[1]
    }
}

impl Point2D for [f32; 2] {
    #[inline]
    fn x(&self) -> f64 {
        self[0] as f64
    }
    #[inline]
    fn y(&self) -> f64 {
        self[1] as f64
    }
}

impl Point2D for (f64, f64) {
    #[inline]
    fn x(&self) -> f64 {
        self.0
    }
    #[inline]
    fn y(&self) -> f64 {
        self.1
    }
}

impl<'a, P: Point2D> Point2D for &'a P {
    #[inline]
    fn x(&self) -> f64 {
        (**self).x()
    }
    #[inline]
    fn y(&self) -> f64 {
        (**self).y()
    }
}
=== index.rs ===
//! Output index types.
//!
//! Stands in for the `template <typename N = uint32_t>` parameter of
//! `mapbox::detail::Earcut`. The C++ code stores `static_cast<N>(i)` inside
//! every node, so the conversion is lossy for narrow `N`; `truncate` reproduces
//! that exactly.

use std::fmt::Display;

/// An integer type usable as a triangle index (`N` in the C++ template).
pub trait IndexType: Copy + Eq + Display {
    /// `static_cast<N>(v)`
    fn from_usize(v: usize) -> Self;
    /// Widen back to `usize`.
    fn to_usize(self) -> usize;

    /// Round trip through `N`, i.e. exactly what `static_cast<N>(i)` keeps.
    #[inline]
    fn truncate(v: usize) -> usize {
        Self::from_usize(v).to_usize()
    }
}

macro_rules! impl_index_type {
    ($($t:ty),*) => {
        $(
            impl IndexType for $t {
                #[inline]
                fn from_usize(v: usize) -> Self {
                    v as $t
                }
                #[inline]
                fn to_usize(self) -> usize {
                    self as usize
                }
            }
        )*
    };
}

impl_index_type!(u8, u16, u32, u64, usize);
